import{_ as a,o as e,c as r,ag as s}from"./chunks/framework.4s5LDCII.js";const c=JSON.parse('{"title":"中国人群身体活动指南（2021）· 分人群推荐量","description":"官方全人群身体活动推荐量：从 2 岁以下婴幼儿到 65 岁以上老人和慢性病患者，每个年龄组该动多少，逐条可溯源。","frontmatter":{"title":"中国人群身体活动指南（2021）· 分人群推荐量","issuer":"国家卫生健康委疾控局指导，中国疾控中心与国家体育总局体科所牵头","source_tier":"一级来源","version":2021,"published":2021,"source_url":"https://www.ndcpa.gov.cn/jbkzzx/c100047/second/list.html?id=cd12caea9b5142679f30891e73a4c81d","pdf_url":"https://www.scdc.sh.cn/shjk/shjk/upload/202402/0201_084223_810.pdf","status":"现行","tags":["权威数据","身体活动","运动","行动清单"],"type":"数据页","reviewed":false,"description":"官方全人群身体活动推荐量：从 2 岁以下婴幼儿到 65 岁以上老人和慢性病患者，每个年龄组该动多少，逐条可溯源。"},"headers":[],"relativePath":"data/physical-activity-2021.md","filePath":"data/physical-activity-2021.md"}'),d={name:"data/physical-activity-2021.md"};function o(i,t,n,h,l,g){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="中国人群身体活动指南-2021-·-分人群推荐量" tabindex="-1">中国人群身体活动指南（2021）· 分人群推荐量 <a class="header-anchor" href="#中国人群身体活动指南-2021-·-分人群推荐量" aria-label="Permalink to &quot;中国人群身体活动指南（2021）· 分人群推荐量&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据指南发布版（中华流行病学杂志 2022 年第 43 卷第 1 期）整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><blockquote><p><strong>数据出处</strong>：《中国人群身体活动指南（2021）》，国家卫生健康委疾控局指导、中国疾控中心与国家体育总局体科所牵头（<a href="https://www.ndcpa.gov.cn/jbkzzx/c100047/second/list.html?id=cd12caea9b5142679f30891e73a4c81d" target="_blank" rel="noreferrer">国家疾控局解读页</a> · <a href="https://www.scdc.sh.cn/shjk/shjk/upload/202402/0201_084223_810.pdf" target="_blank" rel="noreferrer">发布版全文 PDF（上海市疾控中心收录）</a>）。· 一级来源</p></blockquote><h2 id="数据速览卡" tabindex="-1">数据速览卡 <a class="header-anchor" href="#数据速览卡" aria-label="Permalink to &quot;数据速览卡&quot;">​</a></h2><p><strong>总则四条</strong>（适用全人群）：动则有益、多动更好、适度量力、贵在坚持；减少静态行为，每天保持身体活跃；身体活动达到推荐量；安全地进行身体活动。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=1" target="_blank" rel="noreferrer">总则</a>）</p><table tabindex="0"><thead><tr><th>人群</th><th>官方推荐量</th><th>出处</th></tr></thead><tbody><tr><td><strong>2 岁及以下</strong></td><td>每天与看护人互动式玩耍；能独立行走的幼儿每天至少 <strong>180 分钟</strong>身体活动；受限时间每次 ≤1 小时；<strong>不建议看屏幕</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=1" target="_blank" rel="noreferrer">二</a></td></tr><tr><td><strong>3～5 岁</strong></td><td>每天至少 <strong>180 分钟</strong>身体活动，其中 <strong>60 分钟</strong>活力玩耍，鼓励户外；静态每次 ≤1 小时；视屏累计 <strong>&lt;1 小时/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=2" target="_blank" rel="noreferrer">三</a></td></tr><tr><td><strong>6～17 岁</strong></td><td>每天至少 <strong>60 分钟</strong>中高强度身体活动，鼓励户外；每周至少 <strong>3 天</strong>肌肉力量和强健骨骼练习；静态每次 ≤1 小时；视屏 <strong>&lt;2 小时/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=2" target="_blank" rel="noreferrer">四</a></td></tr><tr><td><strong>18～64 岁</strong></td><td>每周 <strong>150～300 分钟</strong>中等强度或 <strong>75～150 分钟</strong>高强度有氧（或等量组合）；每周至少 <strong>2 天</strong>肌肉力量练习；保持日常活动并加量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=2" target="_blank" rel="noreferrer">五</a></td></tr><tr><td><strong>65 岁及以上</strong></td><td>成年人推荐同样适用；坚持<strong>平衡、灵活、柔韧</strong>练习；身体不允许 150 分钟时，尽力增加力所能及的活动</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=2" target="_blank" rel="noreferrer">六</a></td></tr><tr><td><strong>慢性病患者</strong></td><td>活动前<strong>咨询医生</strong>并在专业人员指导下进行；身体允许可参照同龄人推荐；不允许时仍鼓励规律活动</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/physical-activity-2021.pdf#page=2" target="_blank" rel="noreferrer">七</a></td></tr></tbody></table><h2 id="与本站词条的关系" tabindex="-1">与本站词条的关系 <a class="header-anchor" href="#与本站词条的关系" aria-label="Permalink to &quot;与本站词条的关系&quot;">​</a></h2><p>各指南词条&quot;🏃动&quot;部分的运动量，与上表同源：<a href="/SageRelay/guides/hypertension-2023.html">高血压</a>（每周 4～7 天、每天 30～60 分钟）、<a href="/SageRelay/guides/diabetes-2023.html">糖尿病</a>（餐后运动每周 ≥5 天）、<a href="/SageRelay/guides/obesity-2024.html">成人肥胖</a>（每周 150～300 分钟 + 抗阻）等均可在本页找到总依据。</p><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>指导/牵头</td><td>国家卫健委疾控局指导；中国疾控中心、国家体育总局体科所牵头</td></tr><tr><td>版本</td><td>2021（现行，节选自人民卫生出版社 2021 年版）</td></tr><tr><td>原文直链</td><td><a href="https://www.scdc.sh.cn/shjk/shjk/upload/202402/0201_084223_810.pdf" target="_blank" rel="noreferrer">发布版全文 PDF</a>（中华流行病学杂志 2022,43(1):5-6）</td></tr></tbody></table>',10)])])}const f=a(d,[["render",o]]);export{c as __pageData,f as default};
